-- =====================================================================
-- Real project data from BAK_SAP_B1_Project_Dashboard_POC.xlsx
-- Replaces ALL project, AR, payment, procurement and adjustment rows.
-- Run in the Supabase SQL Editor AFTER db/supabase-migration.sql (safe to re-run:
-- it clears and reloads the same data every time).
-- =====================================================================

BEGIN;

-- Schema: the AR table already exists; procurement and adjustments are (re)shaped to the workbook.
ALTER TABLE public.project_ar_transactions ADD COLUMN IF NOT EXISTS due_date DATE;
ALTER TABLE public.project_ar_transactions ADD COLUMN IF NOT EXISTS status TEXT;

CREATE TABLE IF NOT EXISTS public.project_procurement (
  id SERIAL PRIMARY KEY,
  project_id TEXT REFERENCES public.projects(project_id),
  customer TEXT,
  amount_bhd NUMERIC(14,2),
  date DATE,
  created_at TIMESTAMPTZ DEFAULT NOW()
);
ALTER TABLE public.project_procurement ADD COLUMN IF NOT EXISTS document_no TEXT;
ALTER TABLE public.project_procurement ADD COLUMN IF NOT EXISTS so_no TEXT;
ALTER TABLE public.project_procurement ADD COLUMN IF NOT EXISTS document_type TEXT;
ALTER TABLE public.project_procurement ADD COLUMN IF NOT EXISTS cost_status TEXT;

CREATE TABLE IF NOT EXISTS public.project_adjustments (
  id SERIAL PRIMARY KEY,
  project_id TEXT REFERENCES public.projects(project_id),
  customer TEXT,
  description TEXT,
  adjustment_type TEXT,
  amount_bhd NUMERIC(14,2),
  date DATE,
  reference TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);
ALTER TABLE public.project_adjustments ADD COLUMN IF NOT EXISTS so_no TEXT;
CREATE INDEX IF NOT EXISTS idx_project_procurement_project_id ON public.project_procurement(project_id);
CREATE INDEX IF NOT EXISTS idx_project_adjustments_project_id ON public.project_adjustments(project_id);

-- Clear the dependent tables first.
DELETE FROM public.project_adjustments;
DELETE FROM public.project_retention;
DELETE FROM public.project_procurement;
DELETE FROM public.project_ar_transactions;

-- PROJECTS (30). Upserted rather than deleted: project_retention rows reference them.

-- RETENTION (30, from the workbook Retention sheet)

-- AR INVOICES (60, status Open)

-- INCOMING PAYMENTS (30, status Paid)

-- PROCUREMENT (180: purchase orders + AP invoices)

-- ADJUSTMENTS (60: credit + debit notes)

COMMIT;
